import threading
import time
import os
import hashlib
import secrets
import re
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('FLASK_SECRET', secrets.token_hex(32))

# Thread-safe session store
class SessionStore:
    def __init__(self):
        self._lock = threading.Lock()
        self._sessions = {}  # session_id -> {user_id, role, mfa_verified, created_at}
        self._pending_upgrades = {}  # session_id -> {new_role, verified_at}

    def create_session(self, session_id, user_id, role):
        with self._lock:
            self._sessions[session_id] = {
                'user_id': user_id,
                'role': role,
                'mfa_verified': False,
                'created_at': time.time()
            }

    def get_session(self, session_id):
        with self._lock:
            return self._sessions.get(session_id, {}).copy()

    def verify_mfa(self, session_id):
        with self._lock:
            if session_id in self._sessions:
                self._sessions[session_id]['mfa_verified'] = True
                return True
            return False

    def request_role_upgrade(self, session_id, new_role):
        """Stage 1: Request a role upgrade (requires MFA verification first)"""
        with self._lock:
            session = self._sessions.get(session_id)
            if not session:
                return False, "Session not found"
            if not session['mfa_verified']:
                return False, "MFA not verified"
            self._pending_upgrades[session_id] = {
                'new_role': new_role,
                'verified_at': time.time()
            }
            return True, "Upgrade pending approval"

    def approve_upgrade(self, session_id, approver_session_id):
        """Stage 2: Approve a pending upgrade (requires admin approver)
        All checks performed atomically under single lock acquisition."""
        with self._lock:
            # Verify approver is admin
            approver = self._sessions.get(approver_session_id)
            if not approver or approver.get('role') != 'admin':
                return False, "Approver must be admin"

            # Verify the pending upgrade exists and is fresh
            pending = self._pending_upgrades.get(session_id)
            if not pending:
                return False, "No pending upgrade"
            if time.time() - pending['verified_at'] > 300:
                del self._pending_upgrades[session_id]
                return False, "Upgrade request expired"

            # Verify the target session still has MFA verified
            target = self._sessions.get(session_id)
            if not target or not target.get('mfa_verified'):
                return False, "Target MFA no longer valid"

            # Apply the upgrade atomically
            self._sessions[session_id]['role'] = pending['new_role']
            del self._pending_upgrades[session_id]
            return True, "Upgrade applied"

    def revoke_mfa(self, session_id):
        """Revoke MFA verification (e.g., on suspicious activity)"""
        with self._lock:
            if session_id in self._sessions:
                self._sessions[session_id]['mfa_verified'] = False
                return True
            return False

    def invalidate_session(self, session_id):
        with self._lock:
            self._sessions.pop(session_id, None)
            self._pending_upgrades.pop(session_id, None)

store = SessionStore()

# Rate limiting with token bucket
class RateLimiter:
    def __init__(self, rate=10, burst=20):
        self._buckets = {}
        self._lock = threading.Lock()
        self._rate = rate
        self._burst = burst

    def allow(self, key):
        with self._lock:
            now = time.time()
            if key not in self._buckets:
                self._buckets[key] = {'tokens': self._burst, 'last': now}
                return True
            bucket = self._buckets[key]
            elapsed = now - bucket['last']
            bucket['tokens'] = min(self._burst, bucket['tokens'] + elapsed * self._rate)
            bucket['last'] = now
            if bucket['tokens'] >= 1:
                bucket['tokens'] -= 1
                return True
            return False

rate_limiter = RateLimiter()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        session_id = request.headers.get('X-Session-ID')
        if not session_id or not re.match(r'^[a-f0-9]{64}$', session_id):
            return jsonify({'error': 'Invalid session'}), 401
        session = store.get_session(session_id)
        if not session:
            return jsonify({'error': 'Session not found'}), 401
        if time.time() - session['created_at'] > 86400:
            store.invalidate_session(session_id)
            return jsonify({'error': 'Session expired'}), 401
        g.session_id = session_id
        g.session = session
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.session.get('role') != role:
                return jsonify({'error': 'Insufficient privileges'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

# Password hashing helpers using a proper slow KDF (PBKDF2-HMAC-SHA256).
_PBKDF2_ITERATIONS = 200000

def hash_password(password, salt=None):
    """Derive a salted PBKDF2-HMAC-SHA256 hash. Returns hex 'salt$hash'."""
    if salt is None:
        salt = secrets.token_bytes(16)
    elif isinstance(salt, str):
        salt = bytes.fromhex(salt)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, _PBKDF2_ITERATIONS)
    return f"{salt.hex()}${dk.hex()}"

def verify_password(password, stored):
    """Constant-time verification against a stored 'salt$hash' value."""
    try:
        salt_hex, _ = stored.split('$', 1)
    except ValueError:
        return False
    computed = hash_password(password, salt_hex)
    return secrets.compare_digest(computed, stored)

# Compute TOTP-like code for MFA verification
def compute_expected_otp(user_id, window=0):
    """Simplified TOTP - in production would use pyotp"""
    secret = os.environ.get('OTP_SECRET')
    if not secret:
        raise RuntimeError("OTP_SECRET environment variable must be set")
    time_step = int(time.time()) // 30 + window
    h = hashlib.sha256(f"{secret}:{user_id}:{time_step}".encode()).hexdigest()
    # Return 6-digit numeric code
    return str(int(h[:8], 16) % 1000000).zfill(6)

def verify_otp(user_id, provided_code):
    """Verify OTP with time window tolerance"""
    if not re.match(r'^[0-9]{6}$', provided_code):
        return False
    for window in [-1, 0, 1]:
        expected = compute_expected_otp(user_id, window)
        if secrets.compare_digest(provided_code, expected):
            return True
    return False

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        return jsonify({'error': 'Invalid username format'}), 400

    # Simulated auth check (in production: verify against DB).
    # Passwords stored as salted PBKDF2 hashes ('salt$hash').
    user_db = {
        'alice': {'password_hash': hash_password('alice_pass_placeholder'), 'role': 'user', 'user_id': 1001},
        'bob': {'password_hash': hash_password('bob_pass_placeholder'), 'role': 'moderator', 'user_id': 1002},
        'admin': {'password_hash': hash_password('admin_pass_placeholder'), 'role': 'admin', 'user_id': 1000},
    }

    user = user_db.get(username)
    if not user or not verify_password(password, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    session_id = secrets.token_hex(32)
    store.create_session(session_id, user['user_id'], user['role'])

    return jsonify({'session_id': session_id, 'role': user['role']}), 200

@app.route('/api/auth/mfa/verify', methods=['POST'])
@require_auth
def mfa_verify():
    if not rate_limiter.allow(g.session_id):
        return jsonify({'error': 'Rate limited'}), 429

    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    otp_code = str(data.get('code', ''))
    if not verify_otp(g.session['user_id'], otp_code):
        return jsonify({'error': 'Invalid OTP'}), 401

    store.verify_mfa(g.session_id)
    return jsonify({'status': 'MFA verified'}), 200

@app.route('/api/auth/request-upgrade', methods=['POST'])
@require_auth
def request_upgrade():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    new_role = data.get('role', '')
    if new_role not in ('moderator', 'admin'):
        return jsonify({'error': 'Invalid role'}), 400

    success, msg = store.request_role_upgrade(g.session_id, new_role)
    if not success:
        return jsonify({'error': msg}), 403
    return jsonify({'status': msg}), 200

@app.route('/api/auth/approve-upgrade', methods=['POST'])
@require_auth
@require_role('admin')
def approve_upgrade():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    target_session = data.get('target_session', '')
    if not re.match(r'^[a-f0-9]{64}$', target_session):
        return jsonify({'error': 'Invalid session format'}), 400

    success, msg = store.approve_upgrade(target_session, g.session_id)
    if not success:
        return jsonify({'error': msg}), 403
    return jsonify({'status': msg}), 200

