@require_auth
@require_role('admin')
def update_config():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400
    # Validate config key format
    key = data.get('key', '')
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9_.]{0,63}$', key):
        return jsonify({'error': 'Invalid config key'}), 400
    value = str(data.get('value', ''))
    if len(value) > 256:
        return jsonify({'error': 'Value too long'}), 400
    # In production: write to config store
    return jsonify({'status': 'Config updated', 'key': key}), 200

